// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX, Log} from "../src/MONEY_BOX.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
        Log lg = new Log();
        c.SetLogFile(address(lg));
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(address actor, uint128 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 before = __invmut_c_Acc_balance(actor);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        assertTrue(__invmut_c_Acc_balance(actor) == before + amount);
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
